"use strict";(self.webpackChunkcallvault_docs=self.webpackChunkcallvault_docs||[]).push([["7210"],{82696(e){e.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"callvault-1-3-0","metadata":{"permalink":"/updates/callvault-1-3-0","source":"@site/blog/2026-09-17-callvault-1-3-0.md","title":"CallVault 1.3.0","description":"Private cloud backup replaces public file links. Per-track playback and export, Capture setup, and verified updates. A prerelease for device testing.","date":"2026-09-17T00:00:00.000Z","tags":[{"inline":false,"label":"Release","permalink":"/updates/tags/release","description":"CallVault release announcements."},{"inline":false,"label":"Android","permalink":"/updates/tags/android","description":"Posts about the Android app."}],"readingTime":2.25,"hasTruncateMarker":true,"authors":[{"name":"Ahsan Mahmood","title":"Developer, CallVault","url":"https://aoneahsan.com","socials":{"github":"https://github.com/aoneahsan"},"imageURL":"https://github.com/aoneahsan.png","key":"aoneahsan","page":null}],"frontMatter":{"title":"CallVault 1.3.0","description":"Private cloud backup replaces public file links. Per-track playback and export, Capture setup, and verified updates. A prerelease for device testing.","slug":"callvault-1-3-0","authors":["aoneahsan"],"tags":["release","android"],"date":"2026-09-17T00:00:00.000Z"},"unlisted":false,"nextItem":{"title":"CallVault 1.2.0","permalink":"/updates/callvault-1-2-0"}},"content":"Three things stand out in 1.3.0, a prerelease for device testing. A cloud copy is now a private file, a call opens as the separate tracks CallVault found, and one screen tells you whether capture is ready before the call that matters.\\n\\n\x3c!-- truncate --\x3e\\n\\n## Where 1.2.0 left you\\n\\nPlayback, search, notes and export all worked. A backed-up recording, though, was one file behind a public link, and no single track was reachable on its own. Nothing told you, before a call, whether capture was ready.\\n\\n## What 1.3.0 changes\\n\\nA cloud copy is a private file now. You can open it in the app and the web library, and so can a CallVault administrator. No recording has a public link, and private cloud backup is still off until you turn it on. Backups from 1.2.0 were moved already; you do nothing.\\n\\nA call now opens as the tracks CallVault found, each labeled with its real source. Play one. Export one, or ask for a combined recording mixed from what is there.\\n\\nCapture setup lists the microphone, phone state and notifications as Allowed or Needs action, with the battery exemption and the optional accessibility assist below them. It tells you whether capture is ready.\\n\\nWithout an account, you keep 100 recordings on the phone. At the limit, new recording pauses. Nothing is deleted, and playback, search and export keep working; signing in with Google removes the count limit.\\n\\nFree, Pro and Family plans set private cloud backup limits and nothing else. Recording, import, playback, search, notes and export are free on every plan.\\n\\nUpdates come from the website release. The app checks the download\'s size, SHA-256 and version code against the release policy, and the package name and signing certificate against the installed app, then opens the Android installer.\\n\\nEvery new screen ships in English and Urdu, on a refreshed brand color.\\n\\n## What to do with this build\\n\\nThis build is a prerelease for device testing. It sits on the public releases page with its APK and a `SHA256SUMS` file; the download button appears once a release is stable. \\n\\nCheck the APK against SHA256SUMS, install it, then open Capture setup until it reads Capture is ready. Make one test call after that. Your phone decides which audio sources a normal app can hear, and on many phones the other person is clear only on speaker. Listen before you rely on this build for a call that matters.\\n\\nRecording laws vary; you are responsible for getting any consent required where you are. This is general information, not legal advice.\\n\\n[Read setup](/getting-started/install) for the install steps and the SHA-256 check, or the [changelog](/changelog) for the short form."},{"id":"callvault-1-2-0","metadata":{"permalink":"/updates/callvault-1-2-0","source":"@site/blog/2026-07-22-callvault-1-2-0.md","title":"CallVault 1.2.0","description":"A package and platform refresh, web dashboard polish, SEO improvements, and a new documentation site.","date":"2026-07-22T00:00:00.000Z","tags":[{"inline":false,"label":"Release","permalink":"/updates/tags/release","description":"CallVault release announcements."},{"inline":false,"label":"Android","permalink":"/updates/tags/android","description":"Posts about the Android app."}],"readingTime":0.45,"hasTruncateMarker":true,"authors":[{"name":"Ahsan Mahmood","title":"Developer, CallVault","url":"https://aoneahsan.com","socials":{"github":"https://github.com/aoneahsan"},"imageURL":"https://github.com/aoneahsan.png","key":"aoneahsan","page":null}],"frontMatter":{"title":"CallVault 1.2.0","description":"A package and platform refresh, web dashboard polish, SEO improvements, and a new documentation site.","slug":"callvault-1-2-0","authors":["aoneahsan"],"tags":["release","android"],"date":"2026-07-22T00:00:00.000Z"},"unlisted":false,"prevItem":{"title":"CallVault 1.3.0","permalink":"/updates/callvault-1-3-0"},"nextItem":{"title":"CallVault 1.1.0 \u2014 first public release","permalink":"/updates/callvault-1-1-0"}},"content":"CallVault 1.2.0 brings the app\'s dependencies and platform up to date, polishes the web\\ndashboard, and adds this documentation site.\\n\\n\x3c!-- truncate --\x3e\\n\\n## What\'s new\\n\\n- **Platform refresh** \u2014 Riverpod, routing, charts, and other packages brought current.\\n- **Web dashboard polish** \u2014 accessibility fixes, localization, and URL state so tabs,\\n  filters, and search survive a refresh or a shared link.\\n- **SEO and discoverability** improvements across the web surfaces.\\n- **This documentation site.**\\n- **Reliability** \u2014 under-the-hood improvements to the recording and sync pipeline.\\n\\nSee the full [changelog](/changelog), or start with the [install guide](/getting-started/install)."},{"id":"callvault-1-1-0","metadata":{"permalink":"/updates/callvault-1-1-0","source":"@site/blog/2026-07-08-callvault-1-1-0.md","title":"CallVault 1.1.0 \u2014 first public release","description":"Record your own calls, play them back with speed controls, search your history, and optionally back recordings up to storage you control.","date":"2026-07-08T00:00:00.000Z","tags":[{"inline":false,"label":"Release","permalink":"/updates/tags/release","description":"CallVault release announcements."},{"inline":false,"label":"Android","permalink":"/updates/tags/android","description":"Posts about the Android app."}],"readingTime":0.55,"hasTruncateMarker":true,"authors":[{"name":"Ahsan Mahmood","title":"Developer, CallVault","url":"https://aoneahsan.com","socials":{"github":"https://github.com/aoneahsan"},"imageURL":"https://github.com/aoneahsan.png","key":"aoneahsan","page":null}],"frontMatter":{"title":"CallVault 1.1.0 \u2014 first public release","description":"Record your own calls, play them back with speed controls, search your history, and optionally back recordings up to storage you control.","slug":"callvault-1-1-0","authors":["aoneahsan"],"tags":["release","android"],"date":"2026-07-08T00:00:00.000Z"},"unlisted":false,"prevItem":{"title":"CallVault 1.2.0","permalink":"/updates/callvault-1-2-0"}},"content":"The first public release of CallVault \u2014 a personal Android call recorder that keeps your\\ncalls offline-first and, if you want, backs them up to storage you control.\\n\\n\x3c!-- truncate --\x3e\\n\\n## Highlights\\n\\n- **Record your own calls** automatically, with an honest account of what a stock Android\\n  phone can and can\'t capture.\\n- **Play back** with speed controls, and **search** your history by number, contact, or note.\\n- **Favorites and notes** that sync across your devices when you\'re signed in.\\n- **Optional backup** to storage you control \u2014 offline-first, so nothing is lost if you\'re\\n  offline.\\n\\nCallVault isn\'t on Google Play (Play bans silent call recorders); install it by\\n[sideloading the APK](/getting-started/install)."}]}}')}}]);